argv:
$ErrorActionPreference='Stop'
$tmp=Join-Path $env:TEMP 'pc-iphone-json-d2.mjs'
try {
[System.IO.File]::WriteAllText($tmp,@'
const controller=new AbortController();
setTimeout(()=>controller.abort(),3500);
try {
 const res=await fetch('http://127.0.0.1:17447/json/list',{signal:controller.signal});
 const arr=await res.json();
 console.log(JSON.stringify({ok:true,count:arr.length,tabs:arr.filter(t=>t.type==='page'&&String(t.url).includes('/telefony/')).map(t=>({id:t.id,title:t.title,url:t.url}))}));
} catch(e) { console.log(JSON.stringify({ok:false,error:String(e).slice(0,120)})); }
process.exit(0);
'@,[System.Text.UTF8Encoding]::new($false))
& node.exe $tmp
} finally { Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue }
